#[inline(never)]
pub fn materialize(pc: usize) -> u8 {
    // black_box(pc) prevents LTO from enumerating pc over 0..PROGRAM_LEN
    // and pre-computing the entire encoded table at compile time,
    // which would dead-strip the shards and leak the linear buffer.
    let pc = std::hint::black_box(pc);
    let k = pc & 0x3;
    let j = (pc >> 2) as u32;
    let s = PERM[k] as usize;
    let (coeff, off) = COEFFS[s];
    let pos = (j.wrapping_mul(coeff).wrapping_add(off) as usize) % SHARD_LEN;
    match s {
        0 => SHARD_0[pos],
        1 => SHARD_1[pos],
        2 => SHARD_2[pos],
        _ => SHARD_3[pos],
    }
}
